// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Enumerate all positive amounts and any caller other than the contract itself.
        vm.assume(actor != address(c));
        vm.assume(amount > 0);

        uint256 beforeBal = c.getBalance(actor);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 afterBal = c.getBalance(actor);

        assertTrue(afterBal - beforeBal == amount);
    }
}
